typedef struct duckdb_v2_extension_input duckdb_v2_extension_input;

/* --- Types for extension --- */

/* --- Constants for extension --- */

/* --- Function pointer typedefs for extension --- */

/*!
 * Hands back the function-pointer table for the API version the extension was built against, or NULL if this DuckDB
 * cannot serve it.
 *
 * The extension calls it exactly once, first, through DUCKDB_EXTENSION_API_INIT; nothing else in the API may be called
 * before it succeeds. A NULL return means the load has already failed and DuckDB has recorded why, so the entrypoint
 * must return without touching the error slot. Statically linked extensions resolve DuckDB's symbols at link time and
 * never call it, so for those the field is NULL.
 */
typedef const void *(*duckdb_v2_extension_get_api_fn)(duckdb_v2_extension_handle extension, const char *version);

/* --- Functions for extension --- */

/* --- Struct definitions for extension --- */

/*!
 * The single argument to a V2 C extension entrypoint. Borrowed for the duration of the call: none of its fields outlive
 * the entrypoint, and the extension destroys none of them.
 */
struct duckdb_v2_extension_input {
	//! Fetches the versioned function-pointer table. NULL for a statically linked extension.
	duckdb_v2_extension_get_api_fn get_api;

	//! The extension being loaded, and the token get_api takes.
	duckdb_v2_extension_handle extension;

	/*!
	 * A borrowed context to read and run queries through, with a transaction already active. Valid only until the
	 * extension entrypoint returns; do not retain or destroy it.
	 */
	duckdb_v2_context_handle context;

	/*!
	 * A live error slot: never NULL, and never pointing at NULL. Populate it with error_info_set_code, and optionally
	 * error_info_set_text, to fail the load. Do not destroy it -- DuckDB owns it. Pass a slot of your own to calls
	 * whose failure you intend to handle, so only a failure you mean to abort the load with lands here.
	 */
	duckdb_v2_error_info_handle *err;
};

